LESSONS['3-4'] = { book: '', title: ['Tanah gambut dan asid sulfat', 'Peat and acid sulfate soils', '泥炭土与酸性硫酸盐土'], body: [
  ['p', ['Pelajaran ini adalah tentang mengurus tanah pertanian yang sedia ada di tanah gambut dan tanah asid sulfat. Ia bukan panduan untuk membuka kawasan baharu.',
         'This lesson is about managing existing farmland on peat and acid sulfate soils. It is not a guide to opening new land.',
         '本课讲的是如何管理泥炭土和酸性硫酸盐土上的现有农地，并不是开发新土地的指南。']],
  ['h', ['Tanah gambut', 'Peat', '泥炭土']],
  ['table', { head: [['Risiko', 'Risk', '风险'], ['Sebab', 'Why', '原因'], ['Tindakan', 'What to do', '做法']],
    rows: [
      [['Pemendapan', 'Subsidence', '沉降'], ['Gambut yang disalirkan mereput dan mengecut, lalu permukaan tanah turun dan pokok condong.', 'Drained peat decomposes and shrinks, so the land surface sinks and palms lean.', '排水后的泥炭会分解和收缩，地面随之下沉，树木倾斜。'], ['Kekalkan aras air setinggi yang dibenarkan oleh tanaman', 'Keep the water level as high as the crop allows', '在作物允许的范围内尽量保持高水位']],
      [['Kebakaran', 'Fire', '火灾'], ['Gambut kering mudah terbakar dan sukar dipadamkan.', 'Dry peat burns easily and is hard to put out.', '干燥的泥炭容易燃烧，而且难以扑灭。'], ['Tahan air dalam parit pada musim kering; jangan membakar', 'Hold water in the drains in the dry season; never burn', '旱季时在沟中蓄水；绝不焚烧']],
      [['Kesuburan rendah', 'Low fertility', '肥力低'], ['Berasid dan rendah nutrien; baja mudah terlarut resap.', 'Acidic and low in nutrients; fertiliser leaches easily.', '酸性且养分贫乏；肥料容易淋失。'], ['Baja berperingkat mengikut analisis', 'Split fertiliser, guided by analysis', '按分析结果分次施肥']],
    ] }],
  ['p', ['Aras air diukur di dua tempat: pada tolok dalam parit pengumpul, dan dalam telaga pemantauan di tengah blok. Baca dengan kerap dan rekod bacaan. Untuk kelapa sawit sedia ada di gambut, satu manual amalan terbaik menetapkan 50 hingga 70 cm di bawah tebing dalam parit pengumpul, atau 40 hingga 60 cm dalam telaga pemantauan.',
         'The water level is measured in two places: on a gauge in the collection drain, and in a monitoring well in the middle of the block. Read it regularly and record the readings. For existing oil palm on peat, one best-practice manual sets 50 to 70 cm below the bank in collection drains, or 40 to 60 cm in a monitoring well.',
         '水位在两处测量：集水沟内的水位标尺，以及地块中央的监测井。应定期读数并记录。对泥炭土上的现有油棕园，一份最佳管理手册规定集水沟水位低于沟岸 50 至 70 厘米，或监测井水位 40 至 60 厘米。']],
  ['src', { s: 'RSPO, Manual on Best Management Practices for existing oil palm cultivation on peat', u: 'https://rspo.org/wp-content/uploads/2-water-management-the-flood-risk-assessment-template-is-attached-separately.pdf',
    a: ['Kelapa sawit sedia ada di gambut. Tanaman lain memerlukan aras yang berbeza.', 'Existing oil palm on peat. Other crops need different levels.', '泥炭土上的现有油棕园。其他作物需要不同的水位。'] }],
  ['case', ['Di Sessang, Sarawak, mengekalkan aras air bawah tanah yang tinggi didapati lebih baik untuk agronomi kelapa sawit dan pada masa yang sama memperlahankan pereputan gambut.',
            'At Sessang, Sarawak, keeping the groundwater table high was found to be better for oil palm agronomy while also slowing the decomposition of the peat.',
            '在砂拉越 Sessang，研究发现保持较高的地下水位对油棕农艺更有利，同时也减缓了泥炭的分解。']],
  ['src', { s: 'Journal of Oil Palm Research (MPOB), Ground water-table maintenance in relation to peat subsidence at Sessang, Sarawak', u: 'https://jopr.mpob.gov.my/best-management-practices-for-oil-palm-cultivation-on-peat-ground-water-table-maintenance-in-relation-to-peat-subsidence-and-estimation-of-co2-emissions-at-sessang-sarawak/',
    a: ['Satu tapak di Sarawak.', 'One site in Sarawak.', '砂拉越的一个地点。'] }],
  ['p', ['Jabatan Pertanian mempunyai garis panduan khusus untuk pengurusan pertanian di tanah gambut sedia ada, yang bertujuan mencegah kebakaran, banjir dan pencemaran.',
         'Jabatan Pertanian has a dedicated guideline for managing agriculture on existing peat, aimed at preventing fire, flooding and pollution.',
         '农业局有一份专门针对现有泥炭地农业管理的指南，旨在防止火灾、洪涝和污染。']],
  ['src', { s: 'Jabatan Pertanian Malaysia, Garis Panduan Pengurusan Pertanian di Tanah Gambut Sedia Ada', u: 'https://www.doa.gov.my/index.php/pages/view/320', a: ['Malaysia; tanah gambut pertanian sedia ada.', 'Malaysia; existing agricultural peat.', '马来西亚；现有的农业泥炭地。'] }],
  ['h', ['Tanah asid sulfat', 'Acid sulfate soils', '酸性硫酸盐土']],
  ['ul', [
    ['Tanah ini mempunyai lapisan sulfida (pirit) yang terkubur. Selagi lapisan itu tepu air, ia stabil.', 'These soils have a buried sulfidic (pyrite) layer. While that layer stays waterlogged, it is stable.', '这类土壤埋藏着硫化物（黄铁矿）层。只要该层保持淹水，它就是稳定的。'],
    ['Apabila saliran menurunkan aras air di bawah lapisan itu, udara masuk dan asid terbentuk. pH boleh jatuh di bawah 3.5.', 'When drainage lowers the water table below that layer, air gets in and acid forms. The pH can fall below 3.5.', '当排水使地下水位降到该层以下，空气进入并生成酸，pH 可降至 3.5 以下。'],
    ['Ketahui kedalaman lapisan sulfida sebelum menggali sebarang parit, dan kekalkan aras air di atasnya selama mungkin.', 'Find the depth of the sulfidic layer before digging any drain, and keep the water table above it for as long as possible.', '开挖任何沟渠之前，先查明硫化物层的深度，并尽可能长时间地保持地下水位高于该层。'],
    ['Parit perlu dibilas dari semasa ke semasa untuk membuang ion toksik.', 'Drains need flushing from time to time to remove toxic ions.', '沟渠需要定期冲洗，以排除有毒离子。'],
    ['Kapur sahaja selalunya tidak mencukupi untuk mengawal keasidan. Saliran berlebihan ialah punca utama kemerosotan tanah ini.', 'Lime alone is often not enough to control the acidity. Over-drainage is a main cause of the degradation of these soils.', '单靠石灰往往不足以控制酸度。过度排水是这类土壤退化的主要原因。'],
  ]],
  ['src', { s: 'FFTC Agricultural Policy Platform; JIRCAS Tropical Agriculture Research Series 15 and 24', u: 'https://ap.fftc.org.tw/node/3179',
    a: ['Prinsip pengurusan umum; sebahagiannya daripada kertas MARDI yang lama.', 'General management principles; partly from older MARDI papers.', '一般管理原则；部分来自较早的 MARDI 文献。'] }],
] };
