UNITS.find(u => u.n === 3).blurb = ['Pemeriksaan di lapangan, persampelan, mengenal tanah Malaysia, dan tanah gambut serta asid sulfat.', 'Field checks, sampling, identifying Malaysian soils, and peat and acid sulfate soils.', '田间检查、取样、辨识马来西亚土壤，以及泥炭土和酸性硫酸盐土。'];
UNITS.find(u => u.n === 5).blurb = ['Disusun mengikut masalah: keasidan, kurang bahan organik, air, pemadatan dan garam.', 'Organised by problem: acidity, low organic matter, water, compaction and salt.', '按问题编排：酸性、有机质不足、水分、压实和盐分。'];

QUIZ[3].push(
  Q(['Apakah yang berlaku apabila tanah gambut disalirkan terlalu dalam?', 'What happens when peat is drained too deeply?', '泥炭土排水过深会怎样？'],
    [['Ia memendap dan lebih mudah terbakar', 'It subsides and burns more easily', '它会沉降并更容易起火'], ['Ia menjadi tanah liat', 'It turns into clay', '它变成黏土'], ['pH-nya naik kepada 8', 'Its pH rises to 8', '它的 pH 升到 8'], ['Ia menjadi lebih subur', 'It becomes more fertile', '它变得更肥沃']],
    ['Gambut yang kering mereput, mengecut dan mudah terbakar.', 'Dry peat decomposes, shrinks and burns easily.', '干燥的泥炭会分解、收缩并容易燃烧。']));
QUIZ[5].push(
  Q(['Pokok layu walaupun tanah lembap. Apakah yang patut diperiksa sebelum menambah baja?', 'Plants wilt although the soil is moist. What should be checked before adding fertiliser?', '土壤湿润而植株仍萎蔫。追肥之前应先检查什么？'],
    [['Garam dalam tanah atau air, dan keadaan akar', 'Salt in the soil or water, and the state of the roots', '土壤或水中的盐分，以及根系状况'], ['Warna batang', 'The colour of the stem', '茎的颜色'], ['Bilangan daun', 'The number of leaves', '叶片数量'], ['Harga baja', 'The price of fertiliser', '肥料价格']],
    ['Garam menyukarkan akar menyerap air; menambah baja menambah garam lagi.', 'Salt makes it hard for roots to take up water; adding fertiliser adds more salt.', '盐分使根系难以吸水；再施肥只会增加盐分。']));
